     *
     * Faceting requires the payload `key` to have a payload index; call
     * [`UpdateOperation::set_payload`](crate::update::UpdateOperation::set_payload)
     * and index the field beforehand.
     *
     * # Errors
     *
     * Returns [`EdgeError::ShardClosed`](crate::error::EdgeError) if the
     * shard is unloaded, or
     * [`EdgeError::OperationError`](crate::error::EdgeError) if the payload
     * key is not indexed.
     */
    fun `facet`(`request`: FacetRequest): FacetResponse
    
    /**
     * Executes a query whose results are grouped by a payload field: at most
     * `request.groups` groups, each holding up to `request.group_size` of
     * the field value's best hits.
     *
     * Points missing the `group_by` field are skipped. The base query's
     * `limit`/`offset` are driven by the grouping itself.
     *
     * # Errors
     *
     * Returns [`EdgeError::ShardClosed`](crate::error::EdgeError) if the
     * shard is unloaded, or
     * [`EdgeError::OperationError`](crate::error::EdgeError) if the base
     * query is invalid.
     */
    fun `queryGroups`(`request`: GroupRequest): List<Group>
    
    /**
     * Returns summary information about the shard: number of segments,
     * total points, indexed vector count, and the payload indexes.
     *
     * Useful for debugging, UI "collection stats" screens, and sanity
     * checks.
     *
     * # Errors
     *
     * Returns [`EdgeError::ShardClosed`](crate::error::EdgeError) if the
     * shard is unloaded.
     */
    fun `info`(): ShardInfo
    
    /**
     * Executes a high-level query, supporting fusion, prefetching,
     * re-ranking, and score thresholds.
     *
     * This is the most general search entry point. For simple nearest-neighbor
     * search use [`EdgeShard::search`] instead.
     *
     * # Errors
     *
     * Returns [`EdgeError::ShardClosed`](crate::error::EdgeError) if the
     * shard is unloaded, or
     * [`EdgeError::OperationError`](crate::error::EdgeError) if the request
     * is invalid or a required payload index is missing.
     */
    fun `query`(`request`: QueryRequest): List<ScoredPoint>
    
    /**
     * Executes several queries as one planned batch.
     *
     * Returns one result list per request, in the same order as `request.queries`.
     * Prefer this over repeated [`EdgeShard::query`] calls when issuing
     * several independent queries against the same shard: the batch is
     * planned as a whole, so its searches share one pass over the segments
     * and queries that differ only in their vector are scored together.
     *
     * # Errors
     *
     * Returns [`EdgeError::ShardClosed`](crate::error::EdgeError) if the
     * shard is unloaded, or
     * [`EdgeError::OperationError`](crate::error::EdgeError) if any request
     * is invalid or a required payload index is missing.
     */
    fun `queryBatch`(`request`: QueryBatchRequest): List<List<ScoredPoint>>
    
    /**
     * Fetches the points with the given IDs.
     *
     * IDs that do not exist in the shard are simply omitted from the
     * returned list; no error is raised. Duplicate IDs are collapsed — each
     * existing point appears at most once regardless of how many times its ID
     * is requested, and the result order is not guaranteed to match the
     * request order. Set `request.with_payload` and/or `request.with_vector`
     * to control what is included in each returned
     * [`Record`](crate::types::Record).
     *
     * # Errors
     *
     * Returns [`EdgeError::ShardClosed`](crate::error::EdgeError) if the
     * shard is unloaded, or
     * [`EdgeError::InvalidArgument`](crate::error::EdgeError) if a UUID ID
     * or a payload selector key is malformed.
     */
    fun `retrieve`(`request`: RetrieveRequest): List<Record>
    
    /**
