     * with.
     *
     * The returned [`EdgeConfig`] is a snapshot at the time of the call; it
     * is safe to inspect and discard.
     *
     * # Errors
     *
     * Returns [`EdgeError::ShardClosed`] if the shard is unloaded.
     */
    fun `config`(): EdgeConfig
    
    /**
