/**
 * @suppress
 */
public object FfiConverterTypeUpdateOperation: FfiConverter<UpdateOperation, Long> {
    override fun lower(value: UpdateOperation): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): UpdateOperation {
        return UpdateOperation(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): UpdateOperation {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: UpdateOperation) = 8UL

    override fun write(value: UpdateOperation, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



/**
 * Parameters for binary quantization.
 *
 * Binary quantization encodes each vector component with a small number of
 * bits, providing maximum compression for ANN search with optional
 * rescoring.
 */
data class BinaryQuantizationParams (
    /**
     * Memory placement of the quantized data. `None`/`null` follows the
     * original vector storage placement.
     */
    var `memory`: Memory? = null 
    , 
    /**
     * Bits-per-component encoding for the stored index.
     */
    var `encoding`: BinaryQuantizationEncoding? = null 
    , 
    /**
     * Encoding used for the query vector at search time. Defaults to match
     * the index encoding when not set.
     */
    var `queryEncoding`: BinaryQuantizationQueryEncoding? = null 
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeBinaryQuantizationParams: FfiConverterRustBuffer<BinaryQuantizationParams> {
    override fun read(buf: ByteBuffer): BinaryQuantizationParams {
        return BinaryQuantizationParams(
            FfiConverterOptionalTypeMemory.read(buf),
            FfiConverterOptionalTypeBinaryQuantizationEncoding.read(buf),
            FfiConverterOptionalTypeBinaryQuantizationQueryEncoding.read(buf),
        )
    }

    override fun allocationSize(value: BinaryQuantizationParams) = (
            FfiConverterOptionalTypeMemory.allocationSize(value.`memory`) +
            FfiConverterOptionalTypeBinaryQuantizationEncoding.allocationSize(value.`encoding`) +
            FfiConverterOptionalTypeBinaryQuantizationQueryEncoding.allocationSize(value.`queryEncoding`)
    )

    override fun write(value: BinaryQuantizationParams, buf: ByteBuffer) {
            FfiConverterOptionalTypeMemory.write(value.`memory`, buf)
            FfiConverterOptionalTypeBinaryQuantizationEncoding.write(value.`encoding`, buf)
            FfiConverterOptionalTypeBinaryQuantizationQueryEncoding.write(value.`queryEncoding`, buf)
    }
}



