/**
 * A homogeneous set of match values for [`Match::Any`] / [`Match::Except`]:
 * either strings or integers. The type enforces "exactly one" — mirroring the
 * engine's own `AnyVariants`, the gRPC `oneof`, and every official Qdrant
 * client (none of which allows both or neither). An empty set is valid: `Any`
 * then matches nothing and `Except` matches everything.
 */
sealed class AnyVariants {
    
    /**
     * Match against a set of string values.
     */
    data class Strings(
        val `values`: List<kotlin.String>) : AnyVariants()
        
    {
        

        companion object
    }
    
    /**
     * Match against a set of integer values.
     */
    data class Integers(
        val `values`: List<kotlin.Long>) : AnyVariants()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAnyVariants : FfiConverterRustBuffer<AnyVariants>{
    override fun read(buf: ByteBuffer): AnyVariants {
        return when(buf.getInt()) {
            1 -> AnyVariants.Strings(
                FfiConverterSequenceString.read(buf),
                )
            2 -> AnyVariants.Integers(
                FfiConverterSequenceLong.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AnyVariants): ULong = when(value) {
        is AnyVariants.Strings -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceString.allocationSize(value.`values`)
            )
        }
        is AnyVariants.Integers -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceLong.allocationSize(value.`values`)
            )
        }
    }

    override fun write(value: AnyVariants, buf: ByteBuffer) {
        when(value) {
            is AnyVariants.Strings -> {
                buf.putInt(1)
                FfiConverterSequenceString.write(value.`values`, buf)
                Unit
            }
            is AnyVariants.Integers -> {
                buf.putInt(2)
                FfiConverterSequenceLong.write(value.`values`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
