/**
 * A single filter clause, composed into larger filters by [`Filter`].
 */
sealed class Condition {
    
    /**
     * Match against a specific payload field.
     */
    data class Field(
        val `condition`: tech.qdrant.edge.ffi.FieldCondition) : Condition()
        
    {
        

        companion object
    }
    
    /**
     * The given payload key must be absent or empty.
     */
    data class IsEmpty(
        val `key`: kotlin.String) : Condition()
        
    {
        

        companion object
    }
    
    /**
     * The given payload key must hold the JSON `null` value.
     */
    data class IsNull(
        val `key`: kotlin.String) : Condition()
        
    {
        

        companion object
    }
    
    /**
     * Point ID must match any of the listed IDs.
     */
    data class HasId(
        val `ids`: List<tech.qdrant.edge.ffi.PointId>) : Condition()
        
    {
        

        companion object
    }
    
    /**
     * The point must have a vector in the named field.
     */
    data class HasVector(
        val `vectorName`: kotlin.String) : Condition()
        
    {
        

        companion object
    }
    
    /**
     * The point ID must fall into slice `index` of the ID space split into
     * `total` deterministic, disjoint slices. Slices with different `total`
     * values are correlated: slice `0` of `total: 4` is a strict subset of
     * slice `0` of `total: 2`, so a smaller sample is contained in a larger
     * one. `index` must be in `0..total`.
     */
    data class Slice(
        val `total`: kotlin.UInt, 
        val `index`: kotlin.UInt) : Condition()
        
    {
        

        companion object
    }
    
    /**
     * Apply `filter` to the objects of the nested-object array stored under
     * payload `key`: a point matches if at least one array element satisfies
     * the whole filter. Inside, keys are relative to `key` and ID-based
     * conditions are not allowed.
     */
    data class Nested(
        val `key`: kotlin.String, 
        val `filter`: tech.qdrant.edge.ffi.Filter) : Condition()
        
    {
        

        companion object
    }
    
    /**
     * Nested filter — useful for grouping `should` clauses inside a
     * `must` / `must_not`.
     */
    data class Filter(
        val `filter`: tech.qdrant.edge.ffi.Filter) : Condition()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCondition : FfiConverterRustBuffer<Condition>{
    override fun read(buf: ByteBuffer): Condition {
        return when(buf.getInt()) {
            1 -> Condition.Field(
                FfiConverterTypeFieldCondition.read(buf),
                )
            2 -> Condition.IsEmpty(
                FfiConverterString.read(buf),
                )
            3 -> Condition.IsNull(
                FfiConverterString.read(buf),
                )
            4 -> Condition.HasId(
                FfiConverterSequenceTypePointId.read(buf),
                )
            5 -> Condition.HasVector(
                FfiConverterString.read(buf),
                )
            6 -> Condition.Slice(
                FfiConverterUInt.read(buf),
                FfiConverterUInt.read(buf),
                )
            7 -> Condition.Nested(
                FfiConverterString.read(buf),
                FfiConverterTypeFilter.read(buf),
                )
            8 -> Condition.Filter(
                FfiConverterTypeFilter.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Condition): ULong = when(value) {
        is Condition.Field -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFieldCondition.allocationSize(value.`condition`)
            )
        }
        is Condition.IsEmpty -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`key`)
            )
        }
        is Condition.IsNull -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`key`)
            )
        }
        is Condition.HasId -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceTypePointId.allocationSize(value.`ids`)
            )
        }
        is Condition.HasVector -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`vectorName`)
            )
        }
        is Condition.Slice -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`total`)
                + FfiConverterUInt.allocationSize(value.`index`)
            )
        }
        is Condition.Nested -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`key`)
                + FfiConverterTypeFilter.allocationSize(value.`filter`)
            )
        }
        is Condition.Filter -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFilter.allocationSize(value.`filter`)
            )
        }
    }

    override fun write(value: Condition, buf: ByteBuffer) {
        when(value) {
            is Condition.Field -> {
                buf.putInt(1)
                FfiConverterTypeFieldCondition.write(value.`condition`, buf)
                Unit
            }
            is Condition.IsEmpty -> {
                buf.putInt(2)
                FfiConverterString.write(value.`key`, buf)
                Unit
            }
            is Condition.IsNull -> {
                buf.putInt(3)
                FfiConverterString.write(value.`key`, buf)
                Unit
