/**
 * How a [`FieldCondition`] compares a payload field.
 */
sealed class Match {
    
    /**
     * Exact scalar match.
     */
    data class Value(
        val `value`: tech.qdrant.edge.ffi.ValueVariants) : Match()
        
    {
        

        companion object
    }
    
    /**
     * Full-text match: every word of `text` must occur in the field
     * (requires a full-text index on the payload key).
     */
    data class Text(
        val `text`: kotlin.String) : Match()
        
    {
        

        companion object
    }
    
    /**
     * Full-text match: at least one word of `text_any` must occur in the
     * field (requires a full-text index on the payload key).
     */
    data class TextAny(
        val `textAny`: kotlin.String) : Match()
        
    {
        

        companion object
    }
    
    /**
     * Full-text phrase match: the words must occur adjacently and in order
     * (requires a full-text index with phrase matching enabled).
     */
    data class Phrase(
        val `phrase`: kotlin.String) : Match()
        
    {
        

        companion object
    }
    
    /**
     * Prefix match: some word of the field must start with `prefix`
     * (requires a full-text index on the payload key).
     */
    data class Prefix(
        val `prefix`: kotlin.String) : Match()
        
    {
        

        companion object
    }
    
    /**
     * Substring match: some value of the field must contain `substring`
     * (case-sensitive; served by a keyword index, otherwise a payload scan).
     */
    data class Substring(
        val `substring`: kotlin.String) : Match()
        
    {
        

        companion object
    }
    
    /**
     * The field value must equal any of the given values (IN).
     */
    data class Any(
        val `any`: tech.qdrant.edge.ffi.AnyVariants) : Match()
        
    {
        

        companion object
    }
    
    /**
     * The field value must equal none of the given values (NOT IN).
     */
    data class Except(
        val `except`: tech.qdrant.edge.ffi.AnyVariants) : Match()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

