/**
 * The scoring strategy applied by [`QueryRequest`].
 *
 * `Vector` is the most common case — score by vector similarity. `Fusion`
 * and `OrderBy` operate on pre-scored prefetch results.
 */
sealed class ScoringQuery: Disposable  {
    
    /**
     * Score results by vector similarity (the typical search case).
     */
    data class Vector(
        val `query`: tech.qdrant.edge.ffi.Query) : ScoringQuery()
        
    {
        

        companion object
    }
    
    /**
     * Fuse scores from multiple prefetch branches. Requires a non-empty
     * `QueryRequest.prefetches`.
     */
    data class Fusion(
        val `fusion`: tech.qdrant.edge.ffi.Fusion) : ScoringQuery()
        
    {
        

        companion object
    }
    
    /**
     * Rank results by a payload field instead of vector similarity.
     */
    data class OrderBy(
        val `orderBy`: tech.qdrant.edge.ffi.OrderBy) : ScoringQuery()
        
    {
        

        companion object
    }
    
    /**
     * Re-score prefetch results with an arbitrary formula over prefetch
     * scores and payload values. Requires a non-empty
     * `QueryRequest.prefetches`.
     */
    data class Formula(
        /**
         * Root of the formula tree; build it via the [`Expression`]
         * constructors.
         */
        val `expression`: tech.qdrant.edge.ffi.Expression, 
        /**
         * Fallback values for variables missing from a point's payload,
         * keyed by variable name, each encoded as a JSON value string.
         */
        val `defaults`: Map<kotlin.String, kotlin.String>) : ScoringQuery()
        
    {
        

        companion object
    }
    
    /**
     * Maximal Marginal Relevance: nearest-neighbor search re-ranked to
     * trade off relevance against diversity of the result set.
     */
    data class Mmr(
        /**
         * The query vector relevance is measured against.
         */
        val `vector`: tech.qdrant.edge.ffi.NamedVector, 
        /**
         * Vector field to search; `None`/`null` for the default field.
         */
        val `using`: kotlin.String? = null , 
        /**
         * Diversity/relevance trade-off in `[0, 1]`: `0` = full diversity,
         * `1` = full relevance.
         */
        val `lambda`: kotlin.Float, 
        /**
         * Number of nearest-neighbor candidates preselected for re-ranking.
         */
        val `candidatesLimit`: kotlin.ULong) : ScoringQuery()
        
    {
        

        companion object
    }
    
    /**
     * Sample results at random.
     */
    data class Sample(
        val `sample`: tech.qdrant.edge.ffi.Sample) : ScoringQuery()
        
    {
        

        companion object
    }
    

    
    @Suppress("UNNECESSARY_SAFE_CALL") // codegen is much simpler if we unconditionally emit safe calls here
    override fun destroy() {
        when(this) {
            is ScoringQuery.Vector -> {
                
    Disposable.destroy(
        this.`query`
    )
                
            }
            is ScoringQuery.Fusion -> {
                
    Disposable.destroy(
        this.`fusion`
    )
                
            }
            is ScoringQuery.OrderBy -> {
                
    Disposable.destroy(
        this.`orderBy`
    )
                
            }
            is ScoringQuery.Formula -> {
                
    Disposable.destroy(
        this.`expression`,
        this.`defaults`
    )
                
            }
            is ScoringQuery.Mmr -> {
                
    Disposable.destroy(
        this.`vector`,
        this.`using`,
        this.`lambda`,
        this.`candidatesLimit`
    )
                
            }
            is ScoringQuery.Sample -> {
                
    Disposable.destroy(
        this.`sample`
    )
                
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
    

    
    


    companion object
}

